select to_char(month, 'YYYY-MM') as month, saved_pv as "PV", saved_ev as "EV", saved_both as "PV and EV"
from agg_1month_what_if
order by month;

select to_char(year, 'YYYY') as year, saved_pv as "PV", saved_ev as "EV", saved_both as "PV and EV"
from agg_1year_what_if
order by year;

select time, cumulative_saved_pv as "PV saved", cumulative_saved_ev as "EV saved", cumulative_saved_both as "PV and EV saved", cumulative_pv_investment as "PV investment"
from agg_1month_what_if
order by time;

select 'DIE' as value, 'Diesel' as label
union all
select 'SUP', 'Super 95';

select id, name, to_char(purchased_on, 'YYYY-MM-DD') as purchased_on, purchase_mileage
from master_vehicles
order by id;

payload.rawSql:
update master_vehicles
set purchased_on = nullif(${payload.purchased_on:sqlstring}, '')::date,
    purchase_mileage = ${payload.purchase_mileage}
where id = ${payload.id};
